function fmt(d) { return d.toISOString().slice(0, 10) + 'T00:00:00'; }
function labelFmt(d) { const day = String(d.getDate()).padStart(2, '0'); const month = String(d.getMonth() + 1).padStart(2, '0'); return `${day}.${month}.${d.getFullYear()}`; }

const today = new Date();
const yesterday = new Date(today); yesterday.setDate(yesterday.getDate() - 1);

const monthlyStart = new Date(today); monthlyStart.setDate(monthlyStart.getDate() - 365);
const weeklyStart = new Date(today); weeklyStart.setDate(weeklyStart.getDate() - 56);
const countryStart = new Date(today); countryStart.setDate(countryStart.getDate() - 90);
const sourceStart = new Date(today); sourceStart.setDate(sourceStart.getDate() - 90);
const last7Start = new Date(today); last7Start.setDate(last7Start.getDate() - 7);
const campaignStart = new Date(Date.UTC(2026, 7, 20)); // 2026-08-20 taxonomy cutover, fixed (not rolling)

return [{
  json: {
    monthlyStart: fmt(monthlyStart),
    monthlyEnd: fmt(yesterday),
    weeklyStart: fmt(weeklyStart),
    weeklyEnd: fmt(yesterday),
    countryStart: fmt(countryStart),
    countryEnd: fmt(yesterday),
    sourceStart: fmt(sourceStart),
    sourceEnd: fmt(yesterday),
    last7Start: fmt(last7Start),
    last7End: fmt(yesterday),
    campaignStart: fmt(campaignStart),
    campaignEnd: fmt(yesterday),
    campaignRangeLabel: `${labelFmt(campaignStart)} - ${labelFmt(yesterday)}`,
    rangeLabel: `${labelFmt(last7Start)} - ${labelFmt(yesterday)}`,
    generatedAt: today.toISOString()
  }
}];

function num(v) { const n = parseFloat(v); return isNaN(n) ? 0 : n; }

const monthlyItems = $('Get Monthly Trends').all().map(i => i.json);
const weeklyItems = $('Get Weekly Trends').all().map(i => i.json);
const countryItems = $('Get Country Stats').all().map(i => i.json);
const sourceItems = $('Get Traffic By Source').all().map(i => i.json);
const sessionsBySourceMediumItems = $('Get Sessions By Source Medium').all().map(i => i.json);
const newUsersBySourceMediumItems = $('Get New Users By Source Medium').all().map(i => i.json);
const campaignItems = $('Get Campaign Traffic').all().map(i => i.json);
const ranges = $('Compute Rolling Date Ranges').first().json;

function normalizeTrend(items, periodField) {
  return items.map(r => ({
    period: r[periodField] || '',
    activeUsers: num(r.active1DayUsers),
    sessions: num(r.sessions),
    eventCount: num(r.eventCount),
    pageViews: num(r.screenPageViews),
    engagementDuration: num(r.userEngagementDuration),
    sessionsPerUser: num(r.sessionsPerUser)
  })).sort((a, b) => a.period.localeCompare(b.period));
}

const monthly = normalizeTrend(monthlyItems, 'yearMonth');
const weekly = normalizeTrend(weeklyItems, 'yearWeek');

const country = countryItems.map(r => ({
  country: r.country || 'Unknown',
  activeUsers: num(r.active1DayUsers),
  sessions: num(r.sessions),
  eventCount: num(r.eventCount)
})).sort((a, b) => b.activeUsers - a.activeUsers).slice(0, 7);

const source = sourceItems.map(r => ({
  source: r.sessionSource || 'Unknown',
  sessions: num(r.sessions),
  activeUsers: num(r.active1DayUsers)
})).sort((a, b) => b.sessions - a.sessions).slice(0, 7);

const sessionsBySourceMedium = sessionsBySourceMediumItems.map(r => ({
  sourceMedium: r.sessionSourceMedium || 'Unknown',
  engagedSessions: num(r.engagedSessions)
})).sort((a, b) => b.engagedSessions - a.engagedSessions).slice(0, 12);

const newUsersBySourceMedium = newUsersBySourceMediumItems.map(r => ({
  sourceMedium: r.sessionSourceMedium || 'Unknown',
  newUsers: num(r.newUsers)
})).sort((a, b) => b.newUsers - a.newUsers).slice(0, 12);

const CAMPAIGN_SOURCES = ['newsletter', 'lifecycle', 'demo-day'];
const CAMPAIGN_LABELS = { newsletter: 'Newsletter', lifecycle: 'Lifecycle', 'demo-day': 'Demo Day' };
const campaignBySource = {};
campaignItems.forEach(r => {
  const src = (r.sessionSource || '').toLowerCase();
  if (CAMPAIGN_SOURCES.includes(src)) {
    campaignBySource[src] = { activeUsers: num(r.active1DayUsers), sessions: num(r.sessions) };
  }
});
const campaignPerformance = CAMPAIGN_SOURCES.map(src => ({
  source: src,
  label: CAMPAIGN_LABELS[src],
  activeUsers: campaignBySource[src] ? campaignBySource[src].activeUsers : 0,
  sessions: campaignBySource[src] ? campaignBySource[src].sessions : 0
}));

function sum(arr, key) { return arr.reduce((s, x) => s + x[key], 0); }

const totals = {
  totalActiveUsers: sum(monthly, 'activeUsers'),
  totalSessions: sum(monthly, 'sessions'),
  totalEvents: sum(monthly, 'eventCount'),
  totalPageViews: sum(monthly, 'pageViews'),
  totalNewUsersLast7Days: sum(newUsersBySourceMedium, 'newUsers'),
  totalEngagedSessionsLast7Days: sum(sessionsBySourceMedium, 'engagedSessions')
};

return [{
  json: {
    monthly, weekly, country, source, sessionsBySourceMedium, newUsersBySourceMedium, campaignPerformance, totals,
    rangeLabel: ranges.rangeLabel,
    campaignRangeLabel: ranges.campaignRangeLabel,
    generatedAt: ranges.generatedAt
  }
}];

const data = items[0].json;

const MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function formatYearMonth(ym) { if (!ym || ym.length !== 6) return ym; const y = ym.slice(0, 4); const m = Number(ym.slice(4, 6)); return `${MONTH_NAMES[m - 1]} ${y.slice(2)}`; }
function formatYearWeek(yw) { if (!yw || yw.length < 6) return yw; const y = yw.slice(0, 4); const w = yw.slice(4); return `W${w} '${y.slice(2)}`; }

const output = [];

// 1) Monthly trend
output.push({
  json: {
    key: 'monthlyTrend',
    fileName: 'ga4_monthly_trend.png',
    title: 'GA4 Monthly Trend',
    chartConfig: {
      chart: {
        type: 'line',
        data: {
          labels: data.monthly.map(m => formatYearMonth(m.period)),
          datasets: [
            { label: 'Sessions', data: data.monthly.map(m => m.sessions), borderColor: '#3b6cf6', fill: false },
            { label: 'Active Users', data: data.monthly.map(m => m.activeUsers), borderColor: '#1f2a44', fill: false }
          ]
        },
        options: { plugins: { title: { display: true, text: 'Monthly Trend — Sessions & Active Users' } }, scales: { y: { beginAtZero: true } } }
      },
      width: 760, height: 400, backgroundColor: 'white', format: 'png'
    }
  }
});

// 2) Weekly trend
output.push({
  json: {
    key: 'weeklyTrend',
    fileName: 'ga4_weekly_trend.png',
    title: 'GA4 Weekly Trend',
    chartConfig: {
      chart: {
        type: 'bar',
        data: {
          labels: data.weekly.map(w => formatYearWeek(w.period)),
          datasets: [
            { label: 'Sessions', data: data.weekly.map(w => w.sessions), backgroundColor: '#3b6cf6' },
            { label: 'Active Users', data: data.weekly.map(w => w.activeUsers), backgroundColor: '#8fb3ff' }
          ]
        },
        options: { plugins: { title: { display: true, text: 'Weekly Trend — Sessions & Active Users' } }, scales: { y: { beginAtZero: true } } }
      },
      width: 760, height: 400, backgroundColor: 'white', format: 'png'
    }
  }
});

// 3) Country breakdown
output.push({
  json: {
    key: 'countryBreakdown',
    fileName: 'ga4_country_breakdown.png',
    title: 'GA4 Active Users & Sessions by Country',
    chartConfig: {
      chart: {
        type: 'bar',
        data: {
          labels: data.country.map(c => c.country),
          datasets: [
            { label: 'Active Users', data: data.country.map(c => c.activeUsers), backgroundColor: '#1f2a44' },
            { label: 'Sessions', data: data.country.map(c => c.sessions), backgroundColor: '#3b6cf6' }
          ]
        },
        options: { indexAxis: 'y', plugins: { title: { display: true, text: 'Top 7 Countries — Active Users & Sessions (Last 90 Days)' }, legend: { display: true } } }
      },
      width: 760, height: 420, backgroundColor: 'white', format: 'png'
    }
  }
});

// 4) Traffic source breakdown
output.push({
  json: {
    key: 'trafficSource',
    fileName: 'ga4_traffic_source.png',
    title: 'GA4 Sessions by Traffic Source',
    chartConfig: {
      chart: {
        type: 'bar',
        data: { labels: data.source.map(s => s.source), datasets: [{ label: 'Sessions', data: data.source.map(s => s.sessions), backgroundColor: '#3b6cf6' }] },
        options: { indexAxis: 'y', plugins: { title: { display: true, text: 'Sessions by Traffic Source' }, legend: { display: false } } }
      },
      width: 760, height: 420, backgroundColor: 'white', format: 'png'
    }
  }
});

// 5) Email campaign performance (Newsletter, Lifecycle, Demo Day)
output.push({
  json: {
    key: 'campaignPerformance',
    fileName: 'ga4_campaign_performance.png',
    title: 'GA4 Email Campaign Performance',
    chartConfig: {
      chart: {
        type: 'bar',
        data: {
          labels: data.campaignPerformance.map(c => c.label),
          datasets: [
            { label: 'Active Users', data: data.campaignPerformance.map(c => c.activeUsers), backgroundColor: '#1f2a44' },
            { label: 'Sessions', data: data.campaignPerformance.map(c => c.sessions), backgroundColor: '#3b6cf6' }
          ]
        },
        options: { indexAxis: 'y', plugins: { title: { display: true, text: 'Email Campaign Performance — Newsletter, Lifecycle, Demo Day' }, legend: { display: true } } }
      },
      width: 760, height: 360, backgroundColor: 'white', format: 'png'
    }
  }
});

// 6) New users by source/medium (last 7 days)
output.push({
  json: {
    key: 'newUsersBySourceMedium',
    fileName: 'ga4_newusers_source_medium.png',
    title: 'GA4 New Users by Source/Medium (Last 7 Days)',
    chartConfig: {
      chart: {
        type: 'bar',
        data: { labels: data.newUsersBySourceMedium.map(s => s.sourceMedium), datasets: [{ label: 'New Users', data: data.newUsersBySourceMedium.map(s => s.newUsers), backgroundColor: '#1f2a44' }] },
        options: { indexAxis: 'y', plugins: { title: { display: true, text: 'New Users by Source/Medium (Last 7 Days)' }, legend: { display: false } } }
      },
      width: 760, height: 420, backgroundColor: 'white', format: 'png'
    }
  }
});

return output;
